function choiceSelected(choice){const radio=associatedRadio(choice);return !!choice&&(radio?.checked||hasPrimaryChoiceClass(choice)||choice.getAttribute('aria-pressed')==='true'||choice.getAttribute('aria-checked')==='true'||choice.getAttribute('data-state')==='checked'||/(^|\s)(active|selected|checked)(\s|$)/i.test(String(choice.className)));}
async function segmented(f,v){if(v==null||v==='')return false;let wanted=norm(v);if(f==='condition'&&wanted===norm('\u10d2\u10d0\u10e0\u10d4\u10db\u10dd\u10dc\u10e2\u10d4\u10d1\u10e3\u10da\u10d8'))wanted=norm('\u10d0\u10ee\u10d0\u10da\u10d8 \u10d2\u10d0\u10e0\u10d4\u10db\u10dd\u10dc\u10e2\u10d4\u10d1\u10e3\u10da\u10d8');const choice=segmentChoice(f,wanted);if(!choice)return false;if(choiceSelected(choice))return true;if(isSsCreatePage())clickChoiceOnce(choice);else realClick(choice);if(await waitUntil(()=>choiceSelected(segmentChoice(f,wanted)),1000))return true;return isSsCreatePage();}
function bool(f,v){if(typeof v!=='boolean')return false;const e=[...document.querySelectorAll('input[type=checkbox]')].find(x=>matches(x,f));if(e){if(e.checked!==v)e.click();return true;}const l=[...document.querySelectorAll('label,button,[role=checkbox]')].find(x=>visible(x)&&G[f].some(n=>norm(x.textContent).includes(norm(n))));if(!l)return false;const on=l.getAttribute('aria-checked')==='true'||l.classList.contains('active')||l.classList.contains('selected');if(on!==v)l.click();return true;}
async function fill(d){
  if(isSsCreatePage()){ssAppliedExactChoices.clear();ssTransactionCardValue='';}
  const v=values(d);
  v.project=DEFAULT_PROJECT_TYPE;
  let n=await applySsCreateDefaults();
  if(isSsCreatePage())Object.assign(v,{property:'\u10d1\u10d8\u10dc\u10d0',rooms:1,balconyCount:1,bathrooms:1,buildingStatus:'\u10d0\u10ee\u10d0\u10da\u10d8 \u10d0\u10e8\u10d4\u10dc\u10d4\u10d1\u10e3\u10da\u10d8',project:'\u10d0\u10e0\u10d0\u10e1\u10e2\u10d0\u10dc\u10d3\u10d0\u10e0\u10e2\u10e3\u10da\u10d8'});
  if(v.transaction){if(!await stabilizeRentalChoices(v.transaction))throw new Error(dealSelectionError(v.transaction));n++;}
  if(isSsCreatePage()&&await applySsAdditionalInfoDefaults(v))n++;
  const handled={transaction:true};
  for(const f of ['property','buildingStatus','condition','rooms','bedrooms','balconyCount','bathrooms']){handled[f]=await segmented(f,v[f]);if(handled[f])n++;}
  handled.project=isSsCreatePage()||await selectDefaultProjectType();if(handled.project&&!isSsCreatePage())n++;
  for(const f of ['property','condition','currency'])if(!handled[f]&&await select(f,v[f]))n++;
  const locationSelected=await chooseLocation(v.location);if(locationSelected){n++;await sleep(150);}
  for(const f of ['description','price','area','rooms','bedrooms','balconyCount','bathrooms','floor','totalFloors','phone'])if(!handled[f]&&await inputVerified(f,v[f]))n++;
  for(const f of ['elevator','parking','yard'])if(bool(f,v[f]))n++;
  const dealSelected=!v.transaction||await stabilizeRentalChoices(v.transaction,1500);
  if(!dealSelected)throw new Error(dealSelectionError(v.transaction));
  if(!isSsCreatePage()&&!await selectDefaultProjectType())throw new Error(`Project type "${DEFAULT_PROJECT_TYPE}" could not be confirmed.`);
  if(isSsCreatePage()&&!await applySsAdditionalInfoDefaults(v))throw new Error('SS.ge additional information defaults could not be confirmed.');
  return {count:n,locationSelected:!v.location||locationSelected,dealSelected,transaction:v.transaction,formValues:v};
}
function decodeImage(image){if(image.dataUrl){const encoded=String(image.dataUrl).split(',')[1]||'';const binary=atob(encoded);const bytes=new Uint8Array(binary.length);for(let index=0;index<binary.length;index++)bytes[index]=binary.charCodeAt(index);return bytes;}return new Uint8Array(image.bytes||[]);}
