async function bridgeImages(list){const root=document.documentElement,requestId=`${Date.now()}-${Math.random().toString(36).slice(2)}`,payload=document.createElement('script');payload.type='application/json';payload.id=`nikas-images-${requestId}`;payload.textContent=JSON.stringify(list);document.documentElement.appendChild(payload);root.dataset.nikasImagesRequest=requestId;root.dataset.nikasImagesStatus='working';root.dataset.nikasImagesReason='';root.dataset.nikasImagesDebug='';root.dispatchEvent(new Event('nikas:images'));const done=await waitUntil(()=>root.dataset.nikasImagesResponse===requestId&&root.dataset.nikasImagesStatus!=='working',15000);payload.remove();lastImageDebug=done?(root.dataset.nikasImagesDebug||root.dataset.nikasImagesReason||'no-debug'):'MAIN-world image bridge timeout';listingLog('image bridge:',lastImageDebug);if(!done||root.dataset.nikasImagesStatus!=='ok')return 0;try{return Number(JSON.parse(root.dataset.nikasImagesDebug).attached)||0;}catch{return list.length;}}
